      await sdk.waitForTicks(1);
      if(count(kind+' ore')>before) return true;
      const msg=sdk.getState().gameMessages.at(-1)?.text||'';
      if(/depleted|already mined|too low|can't reach/i.test(msg)) break;
    }
  }
  return false;
}
